/bin/bash -lc "python3 - <<'PY'
import gzip,glob
for fn in glob.glob('geo_bulk/*neotenic*Bladder*.gz')[:1]:
 with gzip.open(fn,'rt') as f:
  next(f); next(f)
  for line in f:
   p=line.split('\\t'); gid=p[0]
   if '1-phosphatidylinositol' in gid or 'phosphatidylinositol' in gid:
    print(gid); break
PY"

